const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Sindh province, Pakistan bounding box
  const sindh = ee.Geometry.Rectangle([66.5, 23.8, 72.5, 27.5]);

  // Dates: September 21, 2019 and 2020
  const date1Start = '2019-09-20';
  const date1End = '2019-09-22';
  const date2Start = '2020-09-20';
  const date2End = '2020-09-22';

  // Function to detect water using Landsat 8 MNDWI
  function detectWater(img) {
    const green = img.select('B3');
    const swir1 = img.select('B6');
    const mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
    const water = mndwi.gt(0.3).rename('water');
    return water;
  }

  // Function to mask clouds using QA_PIXEL
  function maskClouds(img) {
    const qa = img.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return img.updateMask(cloudMask);
  }

  // Collect and process 2019 images
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(sindh)
    .filterDate(date1Start, date1End)
    .map(maskClouds);

  const count2019 = col2019.size().getInfo();
  print('2019 Images found: ' + count2019);

  if (count2019 === 0) {
    print('No images for 2019-09-21.');
    print('C1');
    return;
  }

  // Collect and process 2020 images
  const col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(sindh)
    .filterDate(date2Start, date2End)
    .map(maskClouds);

  const count2020 = col2020.size().getInfo();
  print('2020 Images found: ' + count2020);

  if (count2020 === 0) {
    print('No images for 2020-09-21.');
    print('C1');
    return;
  }

  // Mosaic and detect water for 2019
  const water2019 = col2019.map(detectWater).mosaic();
  const waterPixels2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 30,
    maxPixels: 1e9
  }).get('water').getInfo();

  print('Water pixels 2019: ' + waterPixels2019);

  // Mosaic and detect water for 2020
  const water2020 = col2020.map(detectWater).mosaic();
  const waterPixels2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 30,
    maxPixels: 1e9
  }).get('water').getInfo();

  print('Water pixels 2020: ' + waterPixels2020);

  // Validate results
  if (waterPixels2019 === null || waterPixels2020 === null) {
    print('C3');
    return;
  }

  if (waterPixels2019 === 0 && waterPixels2020 === 0) {
    print('No water detected either year.');
    print('B');
    return;
  }

  // Compare water extent
  const increase = waterPixels2020 > waterPixels2019;
  const percentChange = ((waterPixels2020 - waterPixels2019) / waterPixels2019 * 100).toFixed(1);

  print('Change: ' + percentChange + '%');

  if (increase) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
